{
  "name": "数字示波器",
  "name_en": "Digital Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "数字示波器是一种用于采集、显示和分析电信号随时间变化波形的台式测量仪器，常见于电子电路调试、脉冲与时序信号观察、故障诊断以及教学实验中。该设备通常支持多通道输入，并可导出波形数据用于进一步分析。",
  "description_en": "A digital oscilloscope is a bench-top instrument used to acquire, display, and analyze electrical waveforms as they vary over time. It is commonly used for electronics debugging, pulse and timing analysis, fault diagnosis, and laboratory teaching. Such instruments typically support multiple input channels and can export waveform data for further analysis.",
  "tag_hints": [
    "oscilloscope",
    "waveform acquisition",
    "signal measurement",
    "multi-channel signals",
    "electronic debugging",
    "binary waveform transfer",
    "Tektronix"
  ],
  "actions": [
    {
      "action_name": "auto-displayWaveforms",
      "description": "显示指定通道的波形。",
      "description_en": "Display the waveform(s) of the specified channel(s)."
    },
    {
      "action_name": "auto-getWaveform",
      "description": "读取指定通道的波形数据。",
      "description_en": "Read waveform data from the specified channel."
    },
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化示波器并读取设备识别信息。",
      "description_en": "Initialize the oscilloscope and read its identification information."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭示波器会话或结束设备连接。",
      "description_en": "Shut down the oscilloscope session or end the device connection."
    },
    {
      "action_name": "auto-wait",
      "description": "等待示波器完成当前操作。",
      "description_en": "Wait for the oscilloscope to complete the current operation."
    },
    {
      "action_name": "auto-doSendQuery",
      "description": "向示波器发送查询命令并读取文本响应。",
      "description_en": "Send a query command to the oscilloscope and read a text response."
    },
    {
      "action_name": "auto-doSendFloatQuery",
      "description": "向示波器发送查询并读取浮点数结果。",
      "description_en": "Send a query to the oscilloscope and read a floating-point result."
    },
    {
      "action_name": "auto-doSendIntQuery",
      "description": "向示波器发送查询并读取整数结果。",
      "description_en": "Send a query to the oscilloscope and read an integer result."
    },
    {
      "action_name": "auto-doSendCommand",
      "description": "向示波器发送控制命令。",
      "description_en": "Send a control command to the oscilloscope."
    },
    {
      "action_name": "auto-doReadBinaryBlock",
      "description": "从示波器读取二进制数据块。",
      "description_en": "Read a binary data block from the oscilloscope."
    },
    {
      "action_name": "auto-doGetTektronikStatus",
      "description": "查询示波器状态。",
      "description_en": "Query the oscilloscope status."
    },
    {
      "action_name": "auto-doGetStatusUserInfo",
      "description": "获取面向用户的示波器状态信息。",
      "description_en": "Get user-facing status information from the oscilloscope."
    },
    {
      "action_name": "auto-doGetTektronikError",
      "description": "查询示波器错误状态或错误信息。",
      "description_en": "Query the oscilloscope error status or error message."
    },
    {
      "action_name": "auto-showHelp",
      "description": "显示该示波器可用控制操作的帮助信息。",
      "description_en": "Show help information for the available oscilloscope control operations."
    }
  ]
}

